    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "Base implementation of event loop.\n\nThe event loop can be broken up into a multiplexer (the part\nresponsible for notifying us of I/O events) and the event loop proper,\nwhich wraps a multiplexer with functionality for scheduling callbacks,\nimmediately or at a given time in the future.\n\nWhenever a public API takes a callback, subsequent positional\narguments will be passed to the callback if/when it is called.  This\navoids the proliferation of trivial lambdas implementing closures.\nKeyword arguments for the callback are not supported; this is a\nconscious design decision, leaving the door open for keyword arguments\nto modify the meaning of the API call itself.\n" },
        { "BaseEventLoop.create_future", "Create a Future object attached to the loop." },
        { "BaseEventLoop.create_task", "Schedule a coroutine object.\n\nReturn a task object.\n" },
        { "BaseEventLoop.set_task_factory", "Set a task factory that will be used by loop.create_task().\n\nIf factory is None the default task factory will be set.\n\nIf factory is a callable, it should have a signature matching\n'(loop, coro, **kwargs)', where 'loop' will be a reference to the\nactive event loop, 'coro' will be a coroutine object, and **kwargs\nwill be arbitrary keyword arguments that should be passed on to\nTask.  The callable must return a Task.\n" },
        { "BaseEventLoop.get_task_factory", "Return a task factory, or None if the default one is in use." },
        { "BaseEventLoop._make_socket_transport", "Create socket transport." },
        { "BaseEventLoop._make_ssl_transport", "Create SSL transport." },
        { "BaseEventLoop._make_datagram_transport", "Create datagram transport." },
        { "BaseEventLoop._make_read_pipe_transport", "Create read pipe transport." },
        { "BaseEventLoop._make_write_pipe_transport", "Create write pipe transport." },
        { "BaseEventLoop._make_subprocess_transport", "Create subprocess transport." },
        { "BaseEventLoop._write_to_self", "Write a byte to self-pipe, to wake up the event loop.\n\nThis may be called from a different thread.\n\nThe subclass is responsible for implementing the self-pipe.\n" },
        { "BaseEventLoop._process_events", "Process selector events." },
        { "BaseEventLoop.shutdown_asyncgens", "Shutdown all active asynchronous generators." },
        { "BaseEventLoop.shutdown_default_executor", "Schedule the shutdown of the default executor.\n\nThe timeout parameter specifies the amount of time the executor will\nbe given to finish joining. The default value is None, which means\nthat the executor will be given an unlimited amount of time.\n" },
        { "BaseEventLoop._run_forever_setup", "Prepare the run loop to process events.\n\nThis method exists so that custom event loop subclasses (e.g., event loops\nthat integrate a GUI event loop with Python's event loop) have access to all the\nloop setup logic.\n" },
        { "BaseEventLoop._run_forever_cleanup", "Clean up after an event loop finishes the looping over events.\n\nThis method exists so that custom event loop subclasses (e.g., event loops\nthat integrate a GUI event loop with Python's event loop) have access to all the\nloop cleanup logic.\n" },
        { "BaseEventLoop.run_forever", "Run until stop() is called." },
        { "BaseEventLoop.run_until_complete", "Run until the Future is done.\n\nIf the argument is a coroutine, it is wrapped in a Task.\n\nWARNING: It would be disastrous to call run_until_complete()\nwith the same coroutine twice -- it would wrap it in two\ndifferent Tasks and that can't be good.\n\nReturn the Future's result, or raise its exception.\n" },
        { "BaseEventLoop.stop", "Stop running the event loop.\n\nEvery callback already scheduled will still run.  This simply\ninforms run_forever to stop looping after a complete iteration.\n" },
        { "BaseEventLoop.close", "Close the event loop.\n\nThis clears the queues and shuts down the executor,\nbut does not wait for the executor to finish.\n\nThe event loop must not be running.\n" },
        { "BaseEventLoop.is_closed", "Returns True if the event loop was closed." },
        { "BaseEventLoop.is_running", "Returns True if the event loop is running." },
        { "BaseEventLoop.time", "Return the time according to the event loop's clock.\n\nThis is a float expressed in seconds since an epoch, but the\nepoch, precision, accuracy and drift are unspecified and may\ndiffer per event loop.\n" },
        { "BaseEventLoop.call_later", "Arrange for a callback to be called at a given time.\n\nReturn a Handle: an opaque object with a cancel() method that\ncan be used to cancel the call.\n\nThe delay can be an int or float, expressed in seconds.  It is\nalways relative to the current time.\n\nEach callback will be called exactly once.  If two callbacks\nare scheduled for exactly the same time, it is undefined which\nwill be called first.\n\nAny positional arguments after the callback will be passed to\nthe callback when it is called.\n" },
        { "BaseEventLoop.call_at", "Like call_later(), but uses an absolute time.\n\nAbsolute time corresponds to the event loop's time() method.\n" },
        { "BaseEventLoop.call_soon", "Arrange for a callback to be called as soon as possible.\n\nThis operates as a FIFO queue: callbacks are called in the\norder in which they are registered.  Each callback will be\ncalled exactly once.\n\nAny positional arguments after the callback will be passed to\nthe callback when it is called.\n" },
        { "BaseEventLoop._check_thread", "Check that the current thread is the thread running the event loop.\n\nNon-thread-safe methods of this class make this assumption and will\nlikely behave incorrectly when the assumption is violated.\n\nShould only be called when (self._debug == True).  The caller is\nresponsible for checking this condition for performance reasons.\n" },
        { "BaseEventLoop.call_soon_threadsafe", "Like call_soon(), but thread-safe." },
        { "BaseEventLoop._connect_sock", "Create, bind and connect one socket." },
        { "BaseEventLoop.create_connection", "Connect to a TCP server.\n\nCreate a streaming transport connection to a given internet host and\nport: socket family AF_INET or socket.AF_INET6 depending on host (or\nfamily if specified), socket type SOCK_STREAM. protocol_factory must\nbe a callable returning a protocol instance.\n\nThis method is a coroutine which will try to establish the\nconnection in the background.  When successful, the coroutine\nreturns a (transport, protocol) pair.\n" },
        { "BaseEventLoop.sendfile", "Send a file to transport.\n\nReturn the total number of bytes which were sent.\n\nThe method uses high-performance os.sendfile if available.\n\nfile must be a regular file object opened in binary mode.\n\noffset tells from where to start reading the file. If specified,\ncount is the total number of bytes to transmit as opposed to\nsending the file until EOF is reached. File position is updated on\nreturn or also in case of error in which case file.tell()\ncan be used to figure out the number of bytes\nwhich were sent.\n\nfallback set to True makes asyncio to manually read and send\nthe file when the platform does not support the sendfile syscall\n(e.g. Windows or SSL socket on Unix).\n\nRaise SendfileNotAvailableError if the system does not support\nsendfile syscall and fallback is False.\n" },
        { "BaseEventLoop.start_tls", "Upgrade transport to TLS.\n\nReturn a new transport that *protocol* should start using\nimmediately.\n" },
        { "BaseEventLoop.create_datagram_endpoint", "Create datagram connection." },
        { "BaseEventLoop.create_server", "Create a TCP server.\n\nThe host parameter can be a string, in that case the TCP server is\nbound to host and port.\n\nThe host parameter can also be a sequence of strings and in that\ncase the TCP server is bound to all hosts of the sequence.  If\na host appears multiple times (possibly indirectly e.g. when\nhostnames resolve to the same IP address), the server is only bound\nonce to that host.\n\nReturn a Server object which can be used to stop the service.\n\nThis method is a coroutine.\n" },
        { "BaseEventLoop.get_exception_handler", "Return an exception handler, or None if the default one is in use.\n        " },
        { "BaseEventLoop.set_exception_handler", "Set handler as the new event loop exception handler.\n\nIf handler is None, the default exception handler will\nbe set.\n\nIf handler is a callable object, it should have a\nsignature matching '(loop, context)', where 'loop'\nwill be a reference to the active event loop, 'context'\nwill be a dict object (see `call_exception_handler()`\ndocumentation for details about context).\n" },
        { "BaseEventLoop.default_exception_handler", "Default exception handler.\n\nThis is called when an exception occurs and no exception\nhandler is set, and can be called by a custom exception\nhandler that wants to defer to the default behavior.\n\nThis default handler logs the error message and other\ncontext-dependent information.  In debug mode, a truncated\nstack trace is also appended showing where the given object\n(e.g. a handle or future or task) was created, if any.\n\nThe context parameter has the same meaning as in\n`call_exception_handler()`.\n" },
        { "BaseEventLoop.call_exception_handler", "Call the current event loop's exception handler.\n\nThe context argument is a dict containing the following keys:\n\n- 'message': Error message;\n- 'exception' (optional): Exception object;\n- 'future' (optional): Future instance;\n- 'task' (optional): Task instance;\n- 'handle' (optional): Handle instance;\n- 'protocol' (optional): Protocol instance;\n- 'transport' (optional): Transport instance;\n- 'socket' (optional): Socket instance;\n- 'source_traceback' (optional): Traceback of the source;\n- 'handle_traceback' (optional): Traceback of the handle;\n- 'asyncgen' (optional): Asynchronous generator that caused\n                         the exception.\n\nNew keys maybe introduced in the future.\n\nNote: do not overload this method in an event loop subclass.\nFor custom exception handling, use the\n`set_exception_handler()` method.\n" },
        { "BaseEventLoop._add_callback", "Add a Handle to _ready." },
        { "BaseEventLoop._add_callback_signalsafe", "Like _add_callback() but called from a signal handler." },
        { "BaseEventLoop._timer_handle_cancelled", "Notification that a TimerHandle has been cancelled." },
        { "BaseEventLoop._run_once", "Run one full iteration of the event loop.\n\nThis calls all currently ready callbacks, polls for I/O,\nschedules the resulting callbacks, and finally schedules\n'call_later' callbacks.\n" },
        { "Server.wait_closed", "Wait until server is closed and all connections are dropped.\n\n- If the server is not closed, wait.\n- If it is closed, but there are still active connections, wait.\n\nAnyone waiting here will be unblocked once both conditions\n(server is closed and all connections have been dropped)\nhave become true, in either order.\n\nHistorical note: In 3.11 and before, this was broken, returning\nimmediately if the server was already closed, even if there\nwere still active connections. An attempted fix in 3.12.0 was\nstill broken, returning immediately if the server was still\nopen and there were no active connections. Hopefully in 3.12.1\nwe have it right.\n" },
        { "_interleave_addrinfos", "Interleave list of addrinfo tuples by family." },
    };
